import{_ as i,o as e,c as t,a2 as n}from"./chunks/framework.BXA5Pi9t.js";const C=JSON.parse('{"title":"Ceph Testing Weekly 2018-09-12","description":"","frontmatter":{"title":"Ceph Testing Weekly 2018-09-12","date":"2018-09-12T00:00:00.000Z","updated":"2018-09-13T00:00:00.000Z","tags":["[Ceph]","[分布式存储]","[自动化测试]","[CI/CD]","[DevOps]"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2018/Ceph_Testing_Weekly_2018-09-12.md","filePath":"posts/2018/Ceph_Testing_Weekly_2018-09-12.md","lastUpdated":1780459816000}'),s={name:"posts/2018/Ceph_Testing_Weekly_2018-09-12.md"};function p(o,l,a,r,g,_){return e(),t("div",null,[...l[0]||(l[0]=[n('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>： 2023年11月某日</p><p><strong>参会人员</strong>： Greg, Zack, Nathan, Kier, David等</p><p><strong>会议主题</strong>： Ceph分布式存储项目开发与测试进展讨论</p><p><strong>关键细节与讨论议题</strong>：</p><ul><li><strong>人员情况</strong>： <ul><li>由于地理原因和紧急家庭事务，Red Hat的同事无法参加本次会议。</li><li>Greg因产品工作和个人休假未能积极参与，但仍在跟进相关工作。</li><li>Nathan和Kier讨论了Ceph CI Ansible项目的进展和优化方案。</li><li>David分享了OpenSUSE镜像制作的情况。</li></ul></li><li><strong>Ceph CI Ansible项目</strong>： <ul><li><strong>工作流程优化</strong>： <ul><li>讨论了Ceph CI Ansible项目的工作流程，包括部署测试实例、管理worker进程等。</li><li>认为当前的工作流程存在问题，需要改进。</li><li>讨论了使用Systemd服务、独立应用、Ansible模块等方式来优化工作流程。</li></ul></li><li><strong>版本控制和集成测试</strong>： <ul><li>讨论了Ceph CI Ansible项目的版本控制和集成测试问题。</li><li>认为需要将Ceph、Paddle、Papito等项目拆分成独立的Python库或项目，并使用pip进行安装和管理。</li><li>讨论了使用Ansible模块、聚合仓库等方式来实现集成测试。</li></ul></li><li><strong>OpenSUSE镜像制作</strong>： <ul><li>讨论了OpenSUSE镜像制作的情况，包括镜像制作工具和部署过程。</li><li>认为需要将OpenSUSE镜像提供给David，以便用于测试环境搭建。</li></ul></li></ul></li><li><strong>其他议题</strong>： <ul><li>讨论了Ceph项目的Python 3迁移和flake8代码风格检查工具的使用。</li></ul></li></ul><p><strong>决定的事项</strong>：</p><ul><li>Nathan将跟进Ceph CI Ansible项目的优化工作，包括改进工作流程、实现版本控制和集成测试等。</li><li>David将尝试使用OpenSUSE镜像搭建测试环境。</li><li>讨论了使用Ansible模块、聚合仓库等方式来实现集成测试的可行性。</li></ul><p><strong>后续行动计划</strong>：</p><ul><li>Nathan将整理Ceph CI Ansible项目的优化方案，并与团队讨论。</li><li>David将尝试使用OpenSUSE镜像搭建测试环境，并反馈结果。</li><li>团队将讨论集成测试的实现方案。</li></ul><p><strong>关键词</strong>：</p><ul><li>Ceph CI Ansible</li><li>Systemd</li><li>独立应用</li><li>Python库</li><li>pip</li><li>OpenSUSE</li><li>集成测试</li><li>flake8</li><li>Ceph</li><li>分布式存储</li><li>自动化测试</li><li>CI/CD</li><li>DevOps</li></ul>',12)])])}const d=i(s,[["render",p]]);export{C as __pageData,d as default};
